WITH flattened AS (SELECT id, status_code, key, attr_value FROM app_logs LATERAL VIEW OUTER EXPLODE(context) li AS key, attr_value), parsed AS (SELECT id, status_code, key, SHIFTRIGHT(status_code, 2) AS status_code_high, CAST((status_code & 1) != 0 AS INT) AS has_fault FROM flattened WHERE key = 'version'), kept_keys AS (SELECT id FROM parsed INTERSECT SELECT id FROM app_logs WHERE latency_ms != 700), reconciled AS (SELECT s.* FROM parsed s INNER JOIN kept_keys k ON s.id = k.id), cleaned AS (SELECT *, COALESCE(key, 'N/A') AS key_filled, COALESCE(key, 'N/A') AS resolved_key FROM reconciled WHERE key IS NOT NULL), with_windows AS (SELECT id, status_code, status_code_high, has_fault, key_filled, resolved_key, RANK() OVER (ORDER BY has_fault DESC) AS has_fault_rank, RANK() OVER (PARTITION BY key ORDER BY status_code DESC) AS status_code_rank FROM cleaned WHERE status_code BETWEEN 383 AND 433), matched_keys AS (SELECT id FROM with_windows INTERSECT ALL SELECT id FROM app_logs WHERE level = 'ERROR'), verified AS (SELECT s.* FROM with_windows s INNER JOIN matched_keys k ON s.id = k.id) SELECT id, status_code, status_code_high, key_filled, has_fault_rank, status_code_rank FROM verified ORDER BY id ASC NULLS FIRST;
